#!/usr/bin/env node
/**
 * Sync the newest blog post into the LLM-facing indexes.
 *
 * A blog post lives in THREE places that must stay in sync (see CLAUDE.md,
 * "Adding a Blog Post"):
 *   1. src/lib/blog.ts       — the post object, first element of BLOG_POSTS
 *   2. public/llms.txt       — a link line under "## Blog"
 *   3. public/llms-full.txt  — a link line under "## Blog Posts"
 *
 * Editing only blog.ts leaves the indexes stale and the post invisible to
 * llms.txt / llms-full.txt consumers. That has happened more than once when a
 * post was generated by an agent, so this script mechanises the sync:
 *
 *   - Reads the FIRST post in BLOG_POSTS (newest-first ordering)
 *   - Extracts its slug, title, and date directly from the source, so the
 *     title can never be mistyped or drift from blog.ts
 *   - Prepends the link line to both LLMS files (newest-first)
 *   - Advances the "**Last updated:**" stamp to the post's date (never
 *     backwards, so a later edit's stamp is preserved)
 *   - Verifies post-count parity across all three files
 *
 * Idempotent: re-running after a successful sync changes nothing.
 *
 * Usage:
 *   npm run blog:sync-llms          # sync, then verify
 *   npm run blog:sync-llms -- --check   # verify only, no writes (exits 1 on drift)
 *
 * Exits non-zero if the three files disagree, so it is safe to gate a commit on.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const BLOG_TS = join(ROOT, 'src/lib/blog.ts');
const LLMS = join(ROOT, 'public/llms.txt');
const LLMS_FULL = join(ROOT, 'public/llms-full.txt');

const CHECK_ONLY = process.argv.includes('--check');
const BASE_URL = 'https://seqrets.app/blog/';
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'];

const fail = (msg) => { console.error(`\n✗ ${msg}\n`); process.exit(1); };

/** Read a JS string literal ('..', ".." or `..`) starting at the quote index. */
function readStringLiteral(src, quoteIdx) {
  const quote = src[quoteIdx];
  if (!`"'\``.includes(quote)) fail(`expected a string literal at index ${quoteIdx}`);
  let out = '';
  for (let i = quoteIdx + 1; i < src.length; i++) {
    const ch = src[i];
    if (ch === '\\') {
      const next = src[i + 1];
      // Preserve the escape's *value*, matching what the bundler would emit.
      out += next === 'n' ? '\n' : next === 't' ? '\t' : next;
      i++;
      continue;
    }
    if (ch === quote) return out;
    out += ch;
  }
  fail('unterminated string literal in blog.ts');
}

/** Extract slug/title/date of the first (newest) post in BLOG_POSTS. */
function readNewestPost() {
  const src = readFileSync(BLOG_TS, 'utf8');
  const arrIdx = src.indexOf('BLOG_POSTS');
  if (arrIdx === -1) fail('could not find BLOG_POSTS in src/lib/blog.ts');

  const field = (name, from) => {
    const at = src.indexOf(`${name}:`, from);
    if (at === -1) fail(`could not find "${name}:" for the newest post`);
    const q = src.slice(at).search(/["'`]/);
    return { value: readStringLiteral(src, at + q), at };
  };

  const slugAt = src.indexOf('slug:', arrIdx);
  if (slugAt === -1) fail('no posts found in BLOG_POSTS');
  const slug = field('slug', slugAt).value;
  const title = field('title', slugAt).value;
  const date = field('date', slugAt).value;

  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) fail(`date "${date}" is not YYYY-MM-DD`);
  if (!slug || !title) fail('newest post is missing a slug or title');
  return { slug, title, date };
}

/** "2026-08-22" -> "August 22, 2026" (parsed manually to dodge timezone shifts). */
const prettyDate = (iso) => {
  const [y, m, d] = iso.split('-').map(Number);
  return `${MONTHS[m - 1]} ${d}, ${y}`;
};

const countEntries = (text, heading) => {
  const from = text.indexOf(heading);
  if (from === -1) return -1;
  return (text.slice(from).match(
    new RegExp(`^- \\[.*\\]\\(${BASE_URL.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'gm')
  ) || []).length;
};

function syncFile(path, anchor, post, entry) {
  let text = readFileSync(path, 'utf8');
  const label = path.replace(`${ROOT}/`, '');
  let changed = false;

  if (text.includes(`${BASE_URL}${post.slug})`)) {
    console.log(`  ${label}: already lists the post`);
  } else if (CHECK_ONLY) {
    console.log(`  ${label}: MISSING the post`);
  } else {
    if (!text.includes(anchor)) fail(`anchor not found in ${label}: ${JSON.stringify(anchor)}`);
    text = text.replace(anchor, `${anchor}\n${entry}`);
    changed = true;
    console.log(`  ${label}: inserted`);
  }

  // Advance the stamp, never move it backwards.
  const stamp = text.match(/\*\*Last updated:\*\* (.+)/);
  if (stamp) {
    const current = Date.parse(stamp[1]);
    const target = Date.parse(prettyDate(post.date));
    if (!CHECK_ONLY && (Number.isNaN(current) || target > current)) {
      text = text.replace(/\*\*Last updated:\*\* .*/, `**Last updated:** ${prettyDate(post.date)}`);
      changed = true;
      console.log(`  ${label}: stamp -> ${prettyDate(post.date)}`);
    }
  }

  if (changed) writeFileSync(path, text);
}

const post = readNewestPost();
console.log(`\nNewest post: ${post.slug} (${post.date})`);
console.log(`Title: ${post.title.slice(0, 72)}${post.title.length > 72 ? '…' : ''}\n`);

const entry = `- [${post.title}](${BASE_URL}${post.slug})`;
syncFile(LLMS, '- [Blog Index](https://seqrets.app/blog)', post, entry);
syncFile(LLMS_FULL, '## Blog Posts\n', post, entry);

// Parity gate — the whole point of the script.
const blogCount = (readFileSync(BLOG_TS, 'utf8').match(/^ {4}slug: /gm) || []).length;
const llmsCount = countEntries(readFileSync(LLMS, 'utf8'), '## Blog');
const fullCount = countEntries(readFileSync(LLMS_FULL, 'utf8'), '## Blog Posts');

console.log(`\nPost counts — blog.ts: ${blogCount}, llms.txt: ${llmsCount}, llms-full.txt: ${fullCount}`);

if (blogCount !== llmsCount || blogCount !== fullCount) {
  fail('post counts disagree — the three files are out of sync. Do not commit until this is fixed.');
}
console.log('✓ All three files are in sync.\n');
